Given a non negative number n, the task is to convert the given number into an equivalent binary representation.Examples: Input: n = 12Output: "1100"Explanation: the binary representation of 12 is "1100", since 12 = 1×23 + 1×22 + 0×21+ 0×20 = 12Input: n = 33Output: "100001"Explanation: the binary representation of 33 is "100001", since  1×25 + 0×24 + 0×23 + 0×22 + 0×21 + 1×20  = 33Try It YourselfTable of Content[Approach - 1] Division by 2 - O(log₂(n)) Time and O(log₂(n)) Space[Approach - 2] Using Head Recursion - O(log₂(n)) Time and O(log₂(n)) Space[Approach - 3] Using Bitwise Operators - O(log₂(n)) Time and O(log₂(n)) Space[Approach - 4] Using Built-in Methods - O(log₂(n)) Time and O(log₂(n)) Space[Approach - 1] Division by 2 - O(log₂(n)) Time and O(log₂(n)) SpaceTo convert a decimal number to binary, repeatedly divide it by 2 and record the remainders. Reading these remainders in reverse gives the binary representation.
            C++

    #include <iostream>
#include <algorithm>
using namespace std;

string decToBinary(int n) {

    string bin = "";
    while (n > 0) {
        // checking the mod 
		int bit = n%2;
      	bin.push_back('0' + bit);
        n /= 2;
    }

    // reverse the string 
	reverse(bin.begin(), bin.end());
    return bin;
}


int main() {
    int n = 12;
    cout << decToBinary(n);
    return 0;
}


